sub f { my $n = shift; my $y = $n + 1; if ($n > 1) { $y = $y * 3 } return $y } my $v1 = 100; print $v1; my $v2 = 200; print $v2; my $v3 = 300; print $v3; my $v4 = 400; print $v4; my $v5 = 500; print $v5; my $v6 = 600; print $v6; my $v7 = 700; print $v7; my $v8 = 800; print $v8; my $v9 = 900; print $v9; print "|", f(2), "|", f(1), "\n";
